            return new PostCardModel
            {
                Heading = hero?.Heading ?? post.Name,
                Summary = hero?.Summary ?? "",
                Eyebrow = hero?.Eyebrow ?? "",
                ImageUrl = hero?.Image?.GetCropUrl(width: 800, height: 500),
                Url = post.Url()
            };
        }).ToList();
    var model = new PostListingModel { Heading = Model.Content.Heading ?? "Latest stories", Posts = posts };
}
